window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-de35e25d30ee3e7d"]={"versions": [{"id": "FIG-de35e25d30ee3e7d", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Schritts „Write CRC“ innerhalb von AUTOSAR E2E Profile 22 (AUTOSAR_PRS_E2EProtocol). Das Diagramm gilt gleichermaßen für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Funktionen</strong>:</li>\n<li><code>E2E_P22Protect()</code>: Schutzfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><code>E2E_P22Forward()</code>: Weiterleitungsfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><strong>Variablen und Parameter</strong>:</li>\n<li><code>ComputedCRC</code>: Lokale Variable vom Datentyp <code>uint8</code> (1 Byte), welche den vorberechneten Prüfwert hält.</li>\n<li><code>Config-&gt;Offset</code>: Konfigurationsparameter (in Bits), der den Start des E2E-Headers innerhalb des Datenfeldes festlegt.</li>\n<li><code>Data[]</code>: Nutzdaten-Bytearray (<code>uint8*</code>), in dem die CRC platziert wird.</li>\n<li><strong>Aktionsknoten</strong>:</li>\n<li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;Offset/8]</code>: Ausführende Aktion zur Ablage der Prüfsumme.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Knoten</strong>: Eintritt in den Teilschritt „Write CRC“.</li>\n<li><strong>Ablage</strong>: Die 1-Byte große lokale Variable <code>ComputedCRC</code> wird an den berechneten Byte-Index <code>Data[Config-&gt;Offset/8]</code> geschrieben (wobei der konfigurierte Bit-Offset durch 8 dividiert wird).</li>\n<li><strong>Aktivitätsendknoten</strong>: Reguläres Verlassen des Schritts „Write CRC“. Der Ablauf ist streng linear ohne Verzweigungen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung gemäß Anforderung <code>[PRS_E2E_00532]</code>:</p>\n<ul class=\"fig-list\">\n<li>Das Schreiben der CRC muss exakt an der durch <code>Config-&gt;Offset / 8</code> adressierten Byte-Position im Datenarray erfolgen.</li>\n<li>Gilt für Sender- und Forwarding-Pfade (<code>E2E_P22Protect</code> und <code>E2E_P22Forward</code>).</li>\n<li><code>Config-&gt;Offset</code> muss auf ein Byte ausgerichtet sein (Vielfaches von 8), damit der berechnete Index eine ganzzahlige Byte-Grenze trifft.</li>\n<li>Der Aufruf setzt voraus, dass <code>ComputedCRC</code> im vorhergehenden Schritt „Compute CRC“ (<code>[PRS_E2E_00531]</code>) bereits fehlerfrei ermittelt wurde.</li>\n</ul>"}, {"id": "FIG-fed4cb02e0016f61", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Schritts „Write CRC“ innerhalb von AUTOSAR E2E Profile 22 (AUTOSAR_PRS_E2EProtocol). Das Diagramm gilt gleichermaßen für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Funktionen</strong>:</li>\n<li><code>E2E_P22Protect()</code>: Schutzfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><code>E2E_P22Forward()</code>: Weiterleitungsfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><strong>Variablen und Parameter</strong>:</li>\n<li><code>ComputedCRC</code>: Lokale Variable vom Datentyp <code>uint8</code> (1 Byte), welche den vorberechneten Prüfwert hält.</li>\n<li><code>Config-&gt;Offset</code>: Konfigurationsparameter (in Bits), der den Start des E2E-Headers innerhalb des Datenfeldes festlegt.</li>\n<li><code>Data[]</code>: Nutzdaten-Bytearray (<code>uint8*</code>), in dem die CRC platziert wird.</li>\n<li><strong>Aktionsknoten</strong>:</li>\n<li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;Offset/8]</code>: Ausführende Aktion zur Ablage der Prüfsumme.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Knoten</strong>: Eintritt in den Teilschritt „Write CRC“.</li>\n<li><strong>Ablage</strong>: Die 1-Byte große lokale Variable <code>ComputedCRC</code> wird an den berechneten Byte-Index <code>Data[Config-&gt;Offset/8]</code> geschrieben (wobei der konfigurierte Bit-Offset durch 8 dividiert wird).</li>\n<li><strong>Aktivitätsendknoten</strong>: Reguläres Verlassen des Schritts „Write CRC“. Der Ablauf ist streng linear ohne Verzweigungen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung gemäß Anforderung <code>[PRS_E2E_00532]</code>:</p>\n<ul class=\"fig-list\">\n<li>Das Schreiben der CRC muss exakt an der durch <code>Config-&gt;Offset / 8</code> adressierten Byte-Position im Datenarray erfolgen.</li>\n<li>Gilt für Sender- und Forwarding-Pfade (<code>E2E_P22Protect</code> und <code>E2E_P22Forward</code>).</li>\n<li><code>Config-&gt;Offset</code> muss auf ein Byte ausgerichtet sein (Vielfaches von 8), damit der berechnete Index eine ganzzahlige Byte-Grenze trifft.</li>\n<li>Der Aufruf setzt voraus, dass <code>ComputedCRC</code> im vorhergehenden Schritt „Compute CRC“ (<code>[PRS_E2E_00531]</code>) bereits fehlerfrei ermittelt wurde.</li>\n</ul>"}, {"id": "FIG-540ed49716850e65", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Schritts „Write CRC“ innerhalb von AUTOSAR E2E Profile 22 (AUTOSAR_PRS_E2EProtocol). Das Diagramm gilt gleichermaßen für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Funktionen</strong>:</li>\n<li><code>E2E_P22Protect()</code>: Schutzfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><code>E2E_P22Forward()</code>: Weiterleitungsfunktion für E2E Profile 22 (symbolisiert als Sub-Aktivität/Call-Behavior-Aktion).</li>\n<li><strong>Variablen und Parameter</strong>:</li>\n<li><code>ComputedCRC</code>: Lokale Variable vom Datentyp <code>uint8</code> (1 Byte), welche den vorberechneten Prüfwert hält.</li>\n<li><code>Config-&gt;Offset</code>: Konfigurationsparameter (in Bits), der den Start des E2E-Headers innerhalb des Datenfeldes festlegt.</li>\n<li><code>Data[]</code>: Nutzdaten-Bytearray (<code>uint8*</code>), in dem die CRC platziert wird.</li>\n<li><strong>Aktionsknoten</strong>:</li>\n<li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;Offset/8]</code>: Ausführende Aktion zur Ablage der Prüfsumme.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Knoten</strong>: Eintritt in den Teilschritt „Write CRC“.</li>\n<li><strong>Ablage</strong>: Die 1-Byte große lokale Variable <code>ComputedCRC</code> wird an den berechneten Byte-Index <code>Data[Config-&gt;Offset/8]</code> geschrieben (wobei der konfigurierte Bit-Offset durch 8 dividiert wird).</li>\n<li><strong>Aktivitätsendknoten</strong>: Reguläres Verlassen des Schritts „Write CRC“. Der Ablauf ist streng linear ohne Verzweigungen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung gemäß Anforderung <code>[PRS_E2E_00532]</code>:</p>\n<ul class=\"fig-list\">\n<li>Das Schreiben der CRC muss exakt an der durch <code>Config-&gt;Offset / 8</code> adressierten Byte-Position im Datenarray erfolgen.</li>\n<li>Gilt für Sender- und Forwarding-Pfade (<code>E2E_P22Protect</code> und <code>E2E_P22Forward</code>).</li>\n<li><code>Config-&gt;Offset</code> muss auf ein Byte ausgerichtet sein (Vielfaches von 8), damit der berechnete Index eine ganzzahlige Byte-Grenze trifft.</li>\n<li>Der Aufruf setzt voraus, dass <code>ComputedCRC</code> im vorhergehenden Schritt „Compute CRC“ (<code>[PRS_E2E_00531]</code>) bereits fehlerfrei ermittelt wurde.</li>\n</ul>"}], "trans": [{"from": "FIG-de35e25d30ee3e7d", "to": "FIG-fed4cb02e0016f61", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fed4cb02e0016f61", "to": "FIG-540ed49716850e65", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
